schema:
{
  "description": "Apri il ticket di assistenza: compila i campi e scegli il metodo per ciascuno.",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "Quantita": {
        "type": "number",
        "method": "extract",
        "description": "Il numero di pezzi citato."
      },
      "NumeroOrdine": {
        "type": "string",
        "method": "extract",
        "description": "Nell'oggetto e nel testo."
      },
      "TipoRichiesta": {
        "type": "string",
        "method": "classify",
        "description": "Dal testo della richiesta: è una classificazione.",
        "enum": [
          "reso",
          "cambio",
          "rimborso",
          "informazioni"
        ]
      },
      "Urgente": {
        "type": "string",
        "method": "classify",
        "description": "C'è non una richiesta di risposta immediata.",
        "enum": [
          "sì",
          "no"
        ]
      },
      "DataOrdine": {
        "type": "date",
        "method": "extract",
        "description": "Data citata; type \"date\" la normalizza."
      },
      "CodiceCliente": {
        "type": "string",
        "method": "extract",
        "description": "Codice cliente, come scritto."
      }
    }
  }
}
